sys_script_include.script:
gs.include("IllumioConstants");
var IllumioStartDiscovery = Class.create();
IllumioStartDiscovery.prototype = {
    initialize: function() {
        this.logger = new IllumioLogger(null, 'IllumioStartDiscovery');
        this.scheduledJobsGr = new GlideRecordSecure(
            TABLE_SCHEDULED_JOBS
        );
        this.utils = new x_illu2_illumio.IllumioUtils();
    },

    /**
     * Write a terminal, failed data-collection job record and log the reason.
     *
     * Extracted from process(), which spelled the same eight assignments out three times. Every
     * refusal to start discovery has to leave a record behind: the callers of process() are
     * Script Actions and UI Actions that have no other way to tell the user why nothing happened,
     * and a refusal with no job row is indistinguishable from discovery never having been asked
     * for.
     *
     * @param {String} configSysId PCE configuration the refusal belongs to
     * @param {String} operation Short label for current_operation
     * @param {String} message Reason, written to the job log and to syslog
     * @returns {Boolean} Always false, so callers can `return this._refuse(...)`
     */
    _refuse: function(configSysId, operation, message) {
        // NI8. The log line moved BELOW the insert so it can carry the sys_id of the refusal
        // record it is explaining. A refusal still writes a job row, and that row is the only
        // thing the user has to look at -- logging the reason under [-] put the explanation
        // outside the trail of the record it explains. If the insert is refused by an ACL it
        // returns null, setContext renders [-], and this behaves exactly as it did before.
        //
        // initialize() on every path. The original called it only on the already-running branch,
        // so the field-mapping branch inserted on a GlideRecordSecure that had never been
        // initialized -- which works, but skips dictionary defaults and silently carries over
        // field values if the record object is ever reused. One shared this.scheduledJobsGr and
        // three insert sites is exactly that situation.
        this.scheduledJobsGr.initialize();
        this.scheduledJobsGr.job_owner = gs.getUser().getID();
        this.scheduledJobsGr.illumio_pce_configuration = configSysId;
        this.scheduledJobsGr.job_started = new GlideDateTime();
        this.scheduledJobsGr.job_status = JOB_STATUS_FAILED;
        this.scheduledJobsGr.current_operation = operation;
        this.scheduledJobsGr.job_type = JOB_TYPE_DATA_COLLECTION;
        this.scheduledJobsGr.job_completed = new GlideDateTime();
        this.scheduledJobsGr.logs = message;
        var refusedJobSysId = this.scheduledJobsGr.insert();
        this.logger.setContext(refusedJobSysId).error(message);
        return false;
    },

    /**
     * Starts the discovery process
     *
     * **Restructured (ND-3).** The guard and the job creation used to sit INSIDE
     * `while (configClassGr.next())`, and every branch of that body returned. Three consequences,
     * all fixed here, none of which changed what a correctly-configured instance does:
     *
     *  1. **Only the first class mapping was ever checked for a host_name mapping.** The loop
     *     returned on its first iteration whatever it found, so a configuration with three source
     *     tables had two of them unchecked. Discovery then ran over a table it could not derive a
     *     hostname for, and the workloads it produced were dropped at the far end by the MID
     *     Server -- which discards PCE workloads with no hostname by design, so the failure
     *     surfaced as a silently short sync, not as an error. Now EVERY active mapping is
     *     checked and the refusal names the ones that are misconfigured.
     *  2. **"First" was not a defined row.** There was no orderBy, so which mapping got checked
     *     was whatever order the database returned, and a configuration could pass one run and
     *     fail the next with nothing changed. Ordered by source_table now.
     *  3. **Zero active mappings returned `undefined` having created no job record.** The loop
     *     body never ran. The caller saw a falsy return and could not distinguish it from a real
     *     failure, and the user saw nothing at all. That case now gets its own named refusal.
     *
     * The running-job guard and the job insert moved OUT of the loop, where they always belonged:
     * both are per-CONFIGURATION, not per-class-mapping, and running them inside a loop that
     * always returned on its first pass is why that was never visible.
     *
     * @param {String} configSysId PCE configuration to collect for
     * @param {Boolean} isPostSync Tags the job log when discovery follows a sync
     * @returns {Boolean} true if the job is successfully created else false
     */
    process: function(configSysId, isPostSync) {
        var userName = gs.getUser().getID();
        // Check if any job is already in running state
        this.logger.info('Initiating Discovery');

        var configClassGr = new GlideRecordSecure(
            TABLE_CONFIG_CLASS_MAPPING
        );
        configClassGr.addActiveQuery();
        configClassGr.addQuery(
            'illumio_pce_configuration',
            configSysId
        );
        // Stable order so the refusal below lists the offending mappings the same way twice, and
        // so a run cannot pass or fail depending on row order. See point 2 above.
        configClassGr.orderBy('source_table');
        configClassGr.query();

        // Names only, not records. A configuration has a handful of class mappings, not a
        // workload-sized number of them, so this is bounded by configuration size and not by n.
        var mappedTables = [];
        var tablesMissingHostName = [];

        while (configClassGr.next()) {
            var sourceTable = configClassGr.getValue('source_table') ||
                configClassGr.getUniqueValue();
            mappedTables.push(sourceTable);

            var fieldMappingGr = new GlideRecordSecure(
                TABLE_CLASS_FIELD_MAPPING
            );
            fieldMappingGr.addQuery('illumio_config_class_mapping', configClassGr.getUniqueValue());
            fieldMappingGr.addQuery('type', 'host_name');
            fieldMappingGr.addActiveQuery();
            fieldMappingGr.setLimit(1);
            fieldMappingGr.query();
            if (!fieldMappingGr.hasNext()) {
                tablesMissingHostName.push(sourceTable);
            }
        }

        if (mappedTables.length === 0) {
            // NEW REFUSAL. This path previously fell out of the loop and returned undefined with
            // no record written at all.
            return this._refuse(
                configSysId,
                'No Class Mapping Configured',
                'Can not start the discovery as there is no active class mapping configured ' +
                'for this PCE configuration.'
            );
        }

        if (tablesMissingHostName.length > 0) {
            // Message stem kept verbatim -- it is what the existing job records say and what
            // anyone searching the job log or syslog for this failure will search for. The list
            // of tables is appended, because the whole point of checking all of them is being
            // able to say which one is wrong.
            return this._refuse(
                configSysId,
                'PCE Field Mapping Missing',
                'Can not start the discovery as there is no PCE field mapping configured' +
                ' for: ' + tablesMissingHostName.join(', ')
            );
        }

        var runningJobsCount = new GlideAggregate(
            TABLE_SCHEDULED_JOBS
        );
        runningJobsCount.addQuery('illumio_pce_configuration', configSysId);
        runningJobsCount.addQuery('job_status', JOB_STATUS_RUNNING);
        runningJobsCount.addAggregate('COUNT');
        runningJobsCount.query();
        // A COUNT aggregate with no groupBy always returns exactly one row, so `next()` is true
        // and the count is 0 when nothing matches. The original wrapped everything below in this
        // `if` and had an `else` on the count instead; kept as a guard so a query that somehow
        // returns nothing refuses rather than starting a second concurrent job.
        if (!runningJobsCount.next()) {
            return this._refuse(
                configSysId,
                'Already running',
                'Can not start discovery: the running-job check returned no result.'
            );
        }

        if (runningJobsCount.getAggregate('COUNT') > 0) {
            this.logger.info(
                'Can not start discovery as there is already one discovery job in running status.'
            );
            return this._refuse(
                configSysId,
                'Already running',
                'Can not start discovery as there is already one discovery job in running status'
            );
        }

        // Create new job
        this.scheduledJobsGr.initialize();
        this.scheduledJobsGr.job_owner = userName;
        this.scheduledJobsGr.illumio_pce_configuration = configSysId;
        this.scheduledJobsGr.job_started = new GlideDateTime();
        this.scheduledJobsGr.job_status = JOB_STATUS_RUNNING;
        this.scheduledJobsGr.current_operation =
            'Fetching PCE data';
        // W2: no per-line timestamp. The same milestones go to syslog_app_scope,
        // which timestamps them there; the job log is a milestone list, and a
        // timestamp on every line of it was the thing making it unreadable.
        this.scheduledJobsGr.logs =
            'Illumio data collection started' +
            (isPostSync ? ' [POST_SYNC]' : '');
        this.scheduledJobsGr.logs +=
            '\nPHASE - START: Fetch & Store PCE Data';
        this.scheduledJobsGr.job_type = JOB_TYPE_DATA_COLLECTION;
        var jobSysId = this.scheduledJobsGr.insert();
        // NI8. The job id first exists here, so this is where the context goes. The two lines
        // above it -- 'Initiating Discovery' and the already-running message -- stay on [-]
        // correctly: there is no job yet, and in the second case there deliberately never
        // will be. createAsyncJobs' two lines inherit this, setContext having mutated the
        // instance logger.
        this.logger.setContext(jobSysId);

        var discoveryStartStatus = this.createAsyncJobs(jobSysId, configSysId);
        if (!discoveryStartStatus) {
            this.utils.handleFailure(
                jobSysId,
                'Discovery start error',
                'Adding to ECC queue failed',
                configSysId
            );
            return false;
        }
        return true;
    },

    // REACHED BY A COMPUTED NAME, NOT BY A LITERAL ONE. createAsyncJobs does
    // `this[type.toUpperCase() + '_PARAMS']` at :156, so neither of these two appears anywhere in
    // the codebase spelled out. A search for "WORKLOAD_PARAMS" finds only this line, which makes
    // them look dead to any dead-code sweep -- grep-based or otherwise. They are not. Renaming
    // either one means changing the `types` array in createAsyncJobs to match.
    WORKLOAD_PARAMS: {
        keys_to_map: [
            'href',
            'hostname',
            'labels',
            'agent',
            'public_ip',
            'interfaces',
            'ven',
            'enforcement_mode',
            'os_id'
        ],
        primary_key_to_map: 'hostname',
        mapping_table: TABLE_PCE_WORKLOADS_MAPPING,
        result_table: TABLE_PCE_WORKLOADS_MAPPING_STAGE,
    },
    LABEL_PARAMS: {
        keys_to_map: ['href', 'key', 'value'],
        primary_key_to_map: 'value',
        mapping_table: TABLE_PCE_LABELS_MAPPING,
        result_table: TABLE_PCE_LABELS_MAPPING_STAGE,
    },

    /**
     * To create async jobs on PCE
     * @param {String} jobSysId - Job sys id
     * @returns {Boolean} true if the job is successfully created else false
     */
    createAsyncJobs: function(jobSysId, configSysId) {
        this.logger.info('Creating async jobs on PCE');
        var pceConfig = new IllumioGetPCEConfiguration(jobSysId).getConfiguration(configSysId);
        var types = ['workload', 'label'];

        if (pceConfig) {
            try {
                for (var typeIndex in types) {


                    if (this.utils.isJobCancelled(jobSysId)) {
                        break;
                    }

                    var type = types[typeIndex];
                    var params = this[type.toUpperCase() + '_PARAMS'];
                    var parametersToSend = {
                        illumio_pce_configuration_id: configSysId,
                        pce_url: pceConfig.pceUrl,
                        pce_authorization: gs.base64Encode(
                            pceConfig.pceUsername + ':' + pceConfig.pceSecret
                        ),
                        pce_endpoint: '/api/v2/orgs/' +
                            (pceConfig.pceOrganizationID || '1') +
                            '/' +
                            type +
                            's',
                        operation: 'create_async_job',
                        // Were built by concatenating 'x_illu2_illumio_illumio_pce_' + type,
                        // which put four table names in the app that no search for them could
                        // find and that renaming a table would silently miss. They now come off
                        // the _PARAMS object above, which reads the TABLE_* globals.
                        mapping_table_name: params['mapping_table'],
                        result_table_name: params['result_table'],
                        keys_to_map: JSON.stringify(params['keys_to_map']),
                        primary_key_to_map: params['primary_key_to_map'],
                        illumio_scheduled_job_id: jobSysId,
                        job_identifier: type + 's',
                        time_zone: gs.getSession().getTimeZoneName(),
                        enable_pce_mid_proxy: pceConfig.enable_pce_mid_proxy,
                        retry_params: JSON.stringify(pceConfig.retry_params),
                        // Was x_illu2_illumio.payload.batch.size, retired: the only
                        // dot-separated property name in the app, and it sized the MID's
                        // async-job mapping chunk rather than any payload.
                        chunk_size: BATCH_SIZE_STANDARD
                    };
                    var illumioAddToECCQueue = new IllumioAddToECCQueue(
                        'IllumioManageAsyncJobs',
                        pceConfig.midServer,
                        parametersToSend
                    );
                    var addToECCQueue = illumioAddToECCQueue.insert();

                    if (!addToECCQueue) {
                        this.utils.handleFailure(
                            jobSysId,
                            'Adding to ECC queue',
                            'Adding task for async job of fetching ' +
                            type +
                            's to ECC queue failed', configSysId
                        );
                        return false;
                    }
                    this.logger.info('Started async job to fetch PCE ' + type + 's');
                }


                if (this.utils.isJobCancelled(jobSysId)) {
                    return false;
                }
                return true;
            } catch (e) {
                this.utils.handleFailure(
                    jobSysId,
                    'Adding to ECC queue failed',
                    'Exception occurred while adding to ECC queue. Exception: ' +
                    e, configSysId

                );
                return false;
            }
        } else {
            this.utils.handleFailure(
                jobSysId,
                'No PCE configuration found',
                'No PCE configurations available', configSysId
            );
            return false;
        }
    },

    type: 'IllumioStartDiscovery',
};
